cardCss:
.read-card {
    background: transparent;
    border-radius: 16px;
    margin-bottom: 16px;
    perspective: 1200px;
}
.read-flip {
    display: grid;
    min-height: 240px;
    transform-style: preserve-3d;
    transition: transform 0.5s;
}
.read-card.flipped .read-flip { transform: rotateY(180deg); }
.read-face {
    grid-area: 1 / 1;
    backface-visibility: hidden;
    border-radius: 16px;
    padding: 18px 22px;
    box-shadow: 0 1px 3px rgba(15, 118, 110, 0.05);
    border: 1px solid var(--line, #e6e6e6);
    border-left: 4px solid var(--primary, #0f766e);
    background: var(--card-bg, #ffffff);
    display: flex; flex-direction: column;
}
.read-back {
    transform: rotateY(180deg);
    border-left-color: var(--amber, #d97706);
    justify-content: center;
}
.read-card:hover .read-face { box-shadow: 0 10px 26px rgba(15,118,110,0.10); border-color: var(--primary-soft, #ccfbf1); }
.read-head { display: flex; align-items: baseline; gap: 10px; margin-bottom: 14px; flex-wrap: wrap; }
.read-idx { color: var(--ink-3, #64748b); font-size: calc(12px * var(--card-font-scale, 1)); font-weight: 600; }
.read-title { font-size: calc(20px * var(--card-font-scale, 1)); font-weight: 800; color: var(--ink, #1d1d1d); }
.read-source { font-size: calc(12px * var(--card-font-scale, 1)); color: var(--ink-3, #64748b); font-style: italic; }
.read-text {
    font-size: calc(15px * var(--card-font-scale, 1));
    line-height: 1.9;
    color: var(--ink-2, #475569);
    white-space: pre-wrap;
    word-wrap: break-word;
    overflow-wrap: break-word;
    margin-bottom: 14px;
    flex: 1;
}
.read-back-label {
    font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px;
    color: var(--amber, #d97706); margin-bottom: 10px;
}
.read-translation {
    font-size: calc(15px * var(--card-font-scale, 1));
    line-height: 1.9;
    color: var(--ink, #1d1d1d);
    white-space: pre-wrap;
    word-wrap: break-word;
    overflow-wrap: break-word;
    margin-bottom: 14px;
    flex: 1;
}
.read-actions { display: flex; gap: 8px; }
.read-actions .action-btn {
    width: 42px; height: 42px; border: none;
    background: var(--action-btn-bg, #f1f5f9);
    border-radius: 90px; cursor: pointer;
    display: flex; align-items: center; justify-content: center;
    color: var(--ink-3, #64748b); transition: all 0.2s;
}
.read-actions .action-btn i { font-size: 16px; }
.read-actions .action-btn:hover { transform: translateY(-2px); background: var(--primary, #0f766e); color: #fff; }
.read-actions .read-done.is-active { background: var(--primary, #0f766e); color: #fff; }
.read-card.done .read-face { border-left-color: var(--success, #16a34a); background: var(--done-bg, #f0fdf4); }

cardJs:
(function () {
    'use strict';
    window.cardTemplate = {
        name: 'Reading Card',
        fields: [
            { key: 'title', label: '标题', hideable: false },
            { key: 'source', label: '出处' },
            { key: 'text', label: '正文', hideable: false },
            { key: 'translation', label: '中文翻译' }
        ],
        render: function (cardHtml, cardData, api) {
            var data = api.getCardData ? api.getCardData() : cardData;
            var d = data.data || {};
            var hidden = (api.getHiddenFields && api.getHiddenFields()) || {};
            function isHidden(key) { return hidden.has && hidden.has(key); }
            function wrap(key, content) { return isHidden(key) ? '' : content; }
            var done = data.is_favorite === 1;
            var doneActive = done ? 'is-active' : '';
            var flipped = data._flipped ? 'flipped' : '';
            return '<div class="read-card ' + flipped + (done ? ' done' : '') + '" data-card-id="' + data.id + '">' +
                '<div class="read-flip">' +
                '<div class="read-face read-front">' +
                '<div class="read-head">' +
                '<span class="read-idx">' + String(data.current_order).padStart(2, '0') + '</span>' +
                wrap('title', '<span class="read-title">' + (d.title || '') + '</span>') +
                wrap('source', '<span class="read-source">' + (d.source || '') + '</span>') +
                '</div>' +
                wrap('text', '<div class="read-text">' + (d.text || '') + '</div>') +
                '<div class="read-actions">' +
                '<button class="action-btn read-flip-btn" data-action="flip" data-tooltip="' + (flipped ? '返回原文' : '查看翻译') + '"><i class="fa-solid fa-rotate"></i></button>' +
                '<button class="action-btn read-done ' + doneActive + '" data-action="read-done" data-tooltip="' + (done ? '已读' : '标记已阅读') + '"><i class="fa-solid fa-check"></i></button>' +
                '</div>' +
                '</div>' +
                '<div class="read-face read-back">' +
                '<div class="read-back-label">中文翻译</div>' +
                wrap('translation', '<div class="read-translation">' + (d.translation || '') + '</div>') +
                '<div class="read-actions">' +
                '<button class="action-btn read-flip-btn" data-action="flip" data-tooltip="返回原文"><i class="fa-solid fa-rotate"></i></button>' +
                '</div>' +
                '</div>' +
                '</div>' +
                '</div>';
        },
        init: function (cardElement, cardData, api) {
            cardElement.querySelectorAll('[data-action="flip"]').forEach(function (btn) {
                btn.addEventListener('click', function () {
                    cardData._flipped = !cardData._flipped;
                    api.track('flip_view');
                    api.rerender();
                });
            });
            var doneBtn = cardElement.querySelector('[data-action="read-done"]');
            if (doneBtn) doneBtn.addEventListener('click', function () {
                api.toggleFavorite().then(function (d) {
                    if (d.success) api.rerender();
                });
                api.track('read_done');
            });
        },
        update: function (cardElement, cardData, api) {
            var p = cardElement.parentElement;
            if (p) { cardElement.outerHTML = this.render('', cardData, api); }
        }
    };
})();
